// AdminValidations.jsx
// Class diagram: administration.validateInternship() + administration.generateAgreement()
// Use case: Validate Internship + Generate Agreement

import { useState } from "react";
import AdminLayout from "./AdminLayout";

const INIT_VALIDATIONS = [
  {
    id:1, student:"Amira Benali",  studentEmail:"amira@ifa.edu.dz",  university:"IFA",   level:"L3",
    company:"Sonatrach Digital",   companyEmail:"rh@sonatrach.dz",   role:"Full-Stack Developer",
    wilaya:"Alger", type:"On-site", duration:"6 months",
    startDate:"May 05, 2025", endDate:"Nov 05, 2025",
    appliedDate:"Apr 20", acceptedDate:"Apr 24",
    skills:["React","Node.js","PostgreSQL"],
    status:"pending",  // pending | validated | agreement_generated
    validated:false, agreementGenerated:false,
  },
  {
    id:2, student:"Sara Maamri",   studentEmail:"sara@ifa.edu.dz",   university:"IFA",   level:"M1",
    company:"Ooredoo Labs",        companyEmail:"rh@ooredoo.dz",      role:"Data Analyst",
    wilaya:"Alger", type:"Hybrid",  duration:"4 months",
    startDate:"May 10, 2025", endDate:"Sep 10, 2025",
    appliedDate:"Apr 12", acceptedDate:"Apr 22",
    skills:["Python","SQL","Power BI"],
    status:"pending", validated:false, agreementGenerated:false,
  },
  {
    id:3, student:"Lina Zouaoui",  studentEmail:"lina@umbb.dz",      university:"UMBB",  level:"L3",
    company:"Djezzy Tech",         companyEmail:"rh@djezzy.dz",       role:"Backend Engineer",
    wilaya:"Alger", type:"Hybrid",  duration:"4 months",
    startDate:"Apr 28, 2025", endDate:"Aug 28, 2025",
    appliedDate:"Apr 08", acceptedDate:"Apr 18",
    skills:["Python","Django","Redis"],
    status:"agreement_generated", validated:true, agreementGenerated:true,
  },
  {
    id:4, student:"Karim Hadj",    studentEmail:"karim@usthb.dz",    university:"USTHB", level:"M1",
    company:"Mobilis IT",          companyEmail:"rh@mobilis.dz",      role:"Mobile Developer",
    wilaya:"Oran",  type:"On-site", duration:"3 months",
    startDate:"May 01, 2025", endDate:"Aug 01, 2025",
    appliedDate:"Apr 05", acceptedDate:"Apr 15",
    skills:["Flutter","Firebase","Dart"],
    status:"validated", validated:true, agreementGenerated:false,
  },
  {
    id:5, student:"Amine Ferhat",  studentEmail:"amine@usthb.dz",    university:"USTHB", level:"M2",
    company:"Cevital Digital",     companyEmail:"rh@cevital.dz",      role:"DevOps Intern",
    wilaya:"Béjaïa", type:"On-site",duration:"6 months",
    startDate:"Jun 01, 2025", endDate:"Dec 01, 2025",
    appliedDate:"Apr 18", acceptedDate:"Apr 26",
    skills:["Docker","Kubernetes","Linux"],
    status:"pending", validated:false, agreementGenerated:false,
  },
];

const TABS = ["All","Pending","Validated","Agreement generated"];

const STATUS_CFG = {
  pending:              { badge:"badge-orange", label:"Pending",    icon:"⏳" },
  validated:            { badge:"badge-blue",   label:"Validated",  icon:"✅" },
  agreement_generated:  { badge:"badge-green",  label:"PDF issued", icon:"📄" },
};

// Agreement Preview Modal — administration.generateAgreement()
function AgreementModal({ item, onClose, onGenerate }) {
  const [generating, setGenerating] = useState(false);
  const [done, setDone] = useState(false);

  const generate = () => {
    setGenerating(true);
    setTimeout(() => { setGenerating(false); setDone(true); onGenerate(item.id); }, 1800);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-box max-w-lg" onClick={e => e.stopPropagation()}>
        {!done ? (
          <>
            <div className="flex items-center justify-between mb-5">
              <div>
                <h3 className="font-syne font-extrabold text-slate-900 text-xl">Convention de Stage</h3>
                <p className="text-xs text-slate-400 mt-0.5">administration.generateAgreement()</p>
              </div>
              <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-xl">✕</button>
            </div>
            {/* Preview — styled like real agreement */}
            <div className="border border-slate-200 rounded-xl p-5 mb-5 bg-[#fdf9f5]">
              <div className="text-center mb-4 pb-4 border-b border-slate-200">
                <div className="font-syne font-extrabold text-slate-900 text-lg">CONVENTION DE STAGE</div>
                <div className="text-xs text-slate-500 mt-0.5">République Algérienne Démocratique et Populaire</div>
                <div className="text-xs text-slate-500">Ministère de l'Enseignement Supérieur et de la Recherche Scientifique</div>
              </div>
              <div className="space-y-2.5 text-sm">
                {[
                  { k:"Établissement",    v:item.university },
                  { k:"Étudiant(e)",      v:item.student },
                  { k:"Email étudiant",   v:item.studentEmail },
                  { k:"Niveau",           v:item.level },
                  { k:"Entreprise",       v:item.company },
                  { k:"Email entreprise", v:item.companyEmail },
                  { k:"Poste",            v:item.role },
                  { k:"Wilaya",           v:`${item.wilaya} · ${item.type}` },
                  { k:"Date de début",    v:item.startDate },
                  { k:"Date de fin",      v:item.endDate },
                  { k:"Durée",            v:item.duration },
                ].map(({ k, v }) => (
                  <div key={k} className="flex gap-3">
                    <span className="text-slate-400 w-36 shrink-0 text-xs">{k}</span>
                    <span className="font-medium text-slate-800 text-xs">{v}</span>
                  </div>
                ))}
              </div>
              <div className="mt-4 pt-4 border-t border-slate-200 grid grid-cols-2 gap-4 text-center">
                <div>
                  <div className="text-xs text-slate-400 mb-6">Signature étudiant(e)</div>
                  <div className="border-t border-slate-300 pt-1 text-xs text-slate-500">{item.student}</div>
                </div>
                <div>
                  <div className="text-xs text-slate-400 mb-6">Cachet entreprise</div>
                  <div className="border-t border-slate-300 pt-1 text-xs text-slate-500">{item.company}</div>
                </div>
              </div>
            </div>

            <button onClick={generate} disabled={generating}
              className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm flex items-center justify-center gap-2">
              {generating
                ? <><div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />Generating PDF…</>
                : "📄 Generate & Send Convention de Stage"
              }
            </button>
            <button onClick={onClose} className="w-full mt-2 text-xs text-slate-400 hover:text-slate-600 py-2 transition-colors">Cancel</button>
          </>
        ) : (
          <div className="text-center py-6">
            <div className="text-5xl mb-4">📄</div>
            <h3 className="font-syne font-bold text-slate-900 text-xl mb-2">Agreement Generated!</h3>
            <p className="text-sm text-slate-500 font-light mb-2">
              The Convention de Stage for <strong className="text-slate-700">{item.student}</strong> has been generated and sent to both the student and <strong className="text-slate-700">{item.company}</strong>.
            </p>
            <p className="text-xs text-slate-400 font-mono bg-soft/50 px-3 py-1.5 rounded-lg inline-block mb-6">
              REF: AGR-2025-{String(item.id).padStart(4,"0")}
            </p>
            <button onClick={onClose} className="shimmer-btn text-white font-semibold px-8 py-2.5 rounded-xl text-sm block w-full">Done</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function AdminValidations() {
  const [validations, setValidations] = useState(INIT_VALIDATIONS);
  const [tab, setTab]     = useState("All");
  const [selected, setSelected] = useState(null);
  const [modal, setModal] = useState(null);
  const pending = validations.filter(v => v.status === "pending").length;

  // administration.validateInternship()
  const handleValidate = (id) => {
    setValidations(prev => prev.map(v =>
      v.id === id ? { ...v, status:"validated", validated:true } : v
    ));
    setSelected(prev => prev?.id === id ? { ...prev, status:"validated", validated:true } : prev);
  };

  // administration.generateAgreement()
  const handleGenerate = (id) => {
    setValidations(prev => prev.map(v =>
      v.id === id ? { ...v, status:"agreement_generated", agreementGenerated:true } : v
    ));
    setSelected(prev => prev?.id === id ? { ...prev, status:"agreement_generated", agreementGenerated:true } : prev);
  };

  const filtered = validations.filter(v => {
    if (tab === "All") return true;
    if (tab === "Pending")  return v.status === "pending";
    if (tab === "Validated") return v.status === "validated";
    if (tab === "Agreement generated") return v.status === "agreement_generated";
    return true;
  });

  return (
    <AdminLayout active="validations" pendingCount={pending}>
      <div className="p-5 md:p-8">

        {/* Header */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-[#2E7DF7] uppercase tracking-widest mb-1">Validations</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Internship validations</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">
            {pending} pending · {validations.filter(v=>v.validated).length} validated · {validations.filter(v=>v.agreementGenerated).length} agreements issued
          </p>
        </div>

        {/* Diagram note */}
        <div className="anim-fade-up anim-d1 bg-soft/50 border border-soft rounded-xl p-3 mb-5 flex gap-2 items-center">
          <span>📌</span>
          <p className="text-xs text-slate-600">
            Class diagram: <code className="bg-white px-1 rounded">administration.validateInternship()</code> →
            triggers <code className="bg-white px-1 rounded">administration.generateAgreement()</code>
          </p>
        </div>

        {/* Tabs */}
        <div className="anim-fade-up anim-d1 flex flex-wrap gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
          {TABS.map(t => (
            <button key={t} onClick={() => setTab(t)} className={`tab-btn ${tab===t?"active":"inactive"}`}>
              {t}
              <span className="ml-1 opacity-60 text-xs font-bold">
                {t==="All" ? validations.length
                  : t==="Pending" ? validations.filter(v=>v.status==="pending").length
                  : t==="Validated" ? validations.filter(v=>v.status==="validated").length
                  : validations.filter(v=>v.status==="agreement_generated").length}
              </span>
            </button>
          ))}
        </div>

        <div className="grid md:grid-cols-5 gap-5">

          {/* Left list */}
          <div className="md:col-span-2 anim-fade-up anim-d2 space-y-2">
            {filtered.map(v => {
              const s = STATUS_CFG[v.status];
              return (
                <div key={v.id} onClick={() => setSelected(v)}
                  className={`card border cursor-pointer transition-all p-4 ${
                    selected?.id === v.id ? "border-[#2E7DF7] bg-soft/30" : "border-slate-200 hover:border-soft"
                  }`}>
                  <div className="flex items-start justify-between gap-2 mb-1.5">
                    <div>
                      <div className="font-syne font-bold text-slate-800 text-sm">{v.student}</div>
                      <div className="text-xs text-slate-400">{v.university} · {v.level}</div>
                    </div>
                    <span className={`badge ${s.badge} shrink-0`}>{s.label}</span>
                    </div>
                  <div className="text-xs text-slate-500">{v.role} @ {v.company}</div>
                  <div className="text-xs text-slate-400 mt-1">{v.wilaya} · {v.duration} · Accepted {v.acceptedDate}</div>
                </div>
              );
            })}
            {filtered.length === 0 && (
              <div className="text-center py-12">
                <div className="text-4xl mb-2">📭</div>
                <p className="text-sm text-slate-400">No {tab.toLowerCase()} validations.</p>
              </div>
            )}
          </div>

          {/* Right detail */}
          <div className="md:col-span-3 anim-fade-up anim-d3">
            {selected ? (() => {
              const s = STATUS_CFG[selected.status];
              return (
                <div className="card border border-slate-200 p-5 sticky top-4">

                  {/* Header */}
                  <div className="flex items-start gap-4 pb-5 mb-5 border-b border-slate-100">
                    <div className="w-14 h-14 rounded-2xl bg-soft flex items-center justify-center text-xl font-bold text-slate-800 font-syne shrink-0">
                      {selected.student.split(" ").map(n=>n[0]).join("")}
                    </div>
                    <div className="flex-1">
                      <h2 className="font-syne font-extrabold text-slate-900 text-xl">{selected.student}</h2>
                      <p className="text-slate-500 text-sm">{selected.level} · {selected.university}</p>
                      <div className="flex flex-wrap gap-2 mt-2">
                        <span className={`badge ${s.badge}`}>{s.icon} {s.label}</span>
                        <span className="badge badge-slate">📍 {selected.wilaya}</span>
                        <span className="badge badge-slate">⏱ {selected.duration}</span>
                      </div>
                    </div>
                  </div>

                  {/* Details */}
                  <div className="grid grid-cols-2 gap-2.5 mb-5">
                    {[
                      { k:"Student email",  v:selected.studentEmail },
                      { k:"Company",        v:selected.company },
                      { k:"Company email",  v:selected.companyEmail },
                      { k:"Role",           v:selected.role },
                      { k:"Start date",     v:selected.startDate },
                      { k:"End date",       v:selected.endDate },
                    ].map(({ k, v }) => (
                      <div key={k} className="bg-[#fdf9f5] rounded-xl p-3">
                        <div className="text-xs text-slate-400 mb-0.5">{k}</div>
                        <div className="text-xs font-semibold text-slate-700">{v}</div>
                      </div>
                    ))}
                  </div>

                  {/* Skills */}
                  <div className="mb-5">
                    <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-widest mb-2">Skills</h4>
                    <div className="flex flex-wrap gap-1.5">
                      {selected.skills.map(sk => <span key={sk} className="skill-chip">{sk}</span>)}
                    </div>
                  </div>

                  {/* Validation status tracker */}
                  <div className="mb-5">
                    <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-widest mb-3">Process status</h4>
                    <div className="space-y-0">
                      {[
                        { label:"Student applied",          done:true },
                        { label:"Company accepted",         done:true },
                        { label:"Admin validates internship", done:selected.validated },
                        { label:"Agreement generated (PDF)", done:selected.agreementGenerated },
                        ].map((step, i, arr) => (
                        <div key={i} className="flex gap-3">
                          <div className="flex flex-col items-center">
                            <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border-2 shrink-0 ${
                              step.done ? "bg-[#2E7DF7] border-[#2E7DF7] text-white" : "bg-white border-slate-200 text-slate-300"
                            }`}>{step.done ? "✓" : i+1}</div>
                            {i < arr.length-1 && <div className={`w-0.5 h-8 mt-1 ${step.done ? "bg-[#2E7DF7]/30" : "bg-slate-100"}`} />}
                          </div>
                          <div className="pb-4 flex-1">
                            <div className={`text-sm font-semibold ${step.done ? "text-slate-800" : "text-slate-400"}`}>{step.label}</div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="pt-4 border-t border-slate-100 space-y-2">
                    {/* Step 1: validateInternship() */}
                    {selected.status === "pending" && (
                      <button onClick={() => handleValidate(selected.id)}
                        className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm">
                        ✅ Validate internship
                      </button>
                    )}

                    {/* Step 2: generateAgreement() */}
                    {selected.status === "validated" && (
                      <button onClick={() => setModal(selected)}
                        className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm">
                        📄 Generate Convention de Stage
                      </button>
                    )}

                    {selected.status === "agreement_generated" && (
                      <div className="bg-blush/50 border border-blush rounded-xl p-3 flex items-center gap-2 text-sm text-slate-700">
                        <span>📄</span>
                        <div>
                          <div className="font-semibold">Agreement issued</div>
                          <div className="text-xs text-slate-500 font-mono">REF: AGR-2025-{String(selected.id).padStart(4,"0")}</div>
                        </div>
                        <button className="ml-auto text-xs font-semibold text-[#2E7DF7] hover:underline">Download →</button>
                      </div>
                    )}
                  </div>

                </div>
              );
            })() : (
              <div className="card border border-slate-200 p-10 text-center">
                <div className="text-4xl mb-3">👆</div>
                <p className="text-sm text-slate-400">Select a validation to review.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Agreement modal */}
      {modal && (
        <AgreementModal
          item={modal}
          onClose={() => setModal(null)}
          onGenerate={(id) => { handleGenerate(id); setTimeout(() => setModal(null), 2000); }}
        />
      )}
    </AdminLayout>
  );
}
